create database if not exists customer_behaviour;
show databases;

use customer_behaviour;

show tables;

select * from customer;

-- Actual Answers - 
-- Q1 What is the total revenue generated by Male vs Female Customers?

select gender, sum(purchase_amount) 'Total Revenue' from customer group by gender;

-- Q2 Which customers used a discount but still spent more than average purchase amount ?

select customer_id, purchase_amount from customer
where discount_applied = 'Yes'
and purchase_amount > (select avg(purchase_amount) from customer);

-- Q3 Which are the top 5 products with highest average review rating ?

select item_purchased, round(avg(review_rating),2) 'Average Product Rating' from customer group by item_purchased order by 2 desc limit 5;

-- Q4 Compare the average Purchase Amounts between Standard and Express Shipping.

select shipping_type, round(avg(purchase_amount),2) 'Average Purchase Amount' from customer where shipping_type in ('Standard','Express') group by shipping_type;

-- Q5 Do subscribed customers spend more ? Compare average spend and total revenue between subscribers and non-subscribers

select subscription_status, count(*) 'Total Customers' ,round(avg(purchase_amount),2) 'Average Spend', sum(purchase_amount) 'Revenue' from customer group by subscription_status;

-- Q6 Which 5 products have the highest percentage of purchases with discount applied ?

select * from customer;

select item_purchased, round(sum(case when discount_applied = 'Yes' then 1 else 0 end) /count(*) * 100,2) discount_rate
from customer group by item_purchased order by discount_rate desc limit 5; 

-- Q7 Segment Customers in New, Returning and Loyal based on their total number of previous purchases, and show the count of each segment.

-- 1 -> New, 2-10 -> Returning, Else -> Loyal

select * from customer;

-- Query 1 (Own) working -
select 
case when previous_purchases <= 1 then 'New'
	 when previous_purchases between 2 and 10 then 'Returning'
     else 'Loyal' end 'Customer Segements', count(*) 'Number of Customers' from customer group by 1;
     
-- Query 2 - Instructors
     with customer_type as (
     select customer_id, previous_purchases,
     case when previous_purchases = 1 then 'New'
	 when previous_purchases between 2 and 10 then 'Returning'
     else 'Loyal' end as customer_segment
     from customer
     )
     
     select customer_segment, count(*) 'Number of Customers' from customer_type group by customer_segment;

-- Q8 What are the top 3 most purchased products within each category ?

with item_counts as (
select category, item_purchased, count(*) as total_orders, row_number() over (partition by category order by count(*) desc) item_rank from customer group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders from item_counts where item_rank < 4;

-- Writing Query Again for Practice - 

select * from customer;

with item_counts as (
	select category, item_purchased, count(*) total_orders, row_number() over (partition by category order by count(*) desc) item_rank from customer group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders from item_counts where item_rank <= 3;

-- Q9 Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe ?

select * from customer;

select subscription_status, count(*) repeat_buyers from customer
where previous_purchases > 5 group by subscription_status;

-- Q10 What is the revenue contribution of each group ?

select * from customer;

select age_group, sum(purchase_amount) 'Total Revenue' from customer group by age_group order by 2 desc;